# Gol Gumbaz
(211,"place","Modern name of Bijapur mentioned in the Gol Gumbaz box","Vijayapura","கோல் கும்பாஸ் பகுதியில் குறிப்பிடப்பட்ட பிஜாப்பூரின் இன்றைய பெயர்","விஜயபுரா"),
(211,"dynasty","Dynasty for which Bijapur served as capital","Adil Shahi dynasty","பிஜாப்பூர் தலைநகராக இருந்த வம்சம்","ஆதில் ஷாஹி வம்சம்"),
(211,"period","Period of Adil Shahi rule at Bijapur given in the chapter","1480–1686","பாடநூலில் கொடுக்கப்பட்ட பிஜாப்பூர் ஆதில் ஷாஹி காலம்","1480–1686"),
(211,"monument","Mausoleum known as the round dome at Bijapur","Gol Gumbaz","பிஜாப்பூரில் வட்டக் குவிமாடம் என்று அறியப்படும் கல்லறை","கோல் கும்பாஸ்"),
(211,"person","Ruler whose mausoleum is Gol Gumbaz","Mohammad Adil Shah","கோல் கும்பாஸ் கல்லறை அமைக்கப்பட்ட அரசர்","முகமது ஆதில் ஷா"),
(211,"period","Reign of Mohammad Adil Shah given in the chapter","1627–1656","பாடநூலில் கொடுக்கப்பட்ட முகமது ஆதில் ஷாவின் ஆட்சிக்காலம்","1627–1656"),
(211,"material","Main stone used in Gol Gumbaz","Dark grey basalt","கோல் கும்பாஸ் கட்டிடத்தில் பயன்படுத்தப்பட்ட முக்கியக் கல்","கருமை கலந்த சாம்பல் பசால்ட்"),
(211,"number","Number of octagonal corner towers of Gol Gumbaz","Four","கோல் கும்பாஸின் எண்கோண மூலைக் கோபுரங்கள் எண்ணிக்கை","நான்கு"),
(211,"number","Number of storeys in each Gol Gumbaz tower","Seven","கோல் கும்பாஸ் ஒவ்வொரு கோபுரத்தின் தளங்கள் எண்ணிக்கை","ஏழு"),
(211,"ranking","World ranking of the Gol Gumbaz dome stated in the chapter","Second largest after St Peter's Basilica","பாடநூலில் கோல் கும்பாஸ் குவிமாடத்தின் உலக அளவிலான நிலை","செயின்ட் பீட்டர்ஸ் பேராலயத்திற்குப் பின் இரண்டாவது பெரியது"),
(211,"number","Number of cenotaphs on the elevated platform inside Gol Gumbaz","Five","கோல் கும்பாஸ் உயர்ந்த மேடையில் உள்ள நினைவுக் கல்லறைகள் எண்ணிக்கை","ஐந்து"),
(211,"person","Wife of Muhammad Adil Shah represented among Gol Gumbaz cenotaphs","Arus Bibi","கோல் கும்பாஸ் நினைவுக் கல்லறைகளில் உள்ள முகமது ஆதில் ஷாவின் மனைவி","அருஸ் பீபி"),
(211,"person","Favourite mistress of Muhammad Adil Shah represented among Gol Gumbaz cenotaphs","Rambha","கோல் கும்பாஸ் நினைவுக் கல்லறைகளில் உள்ள முகமது ஆதில் ஷாவின் விருப்பத் துணைவி","ரம்பா"),

