def norm(s):
    return " ".join(str(s).split()).strip()

facts=[]; seen=set()
for row in F:
    p,k,de,ae,dt,at=row
    key=(norm(de).lower(),norm(ae).lower())
    if key in seen:
        continue
    seen.add(key)
    facts.append({"page_en":p,"kind":k,"desc_en":norm(de),"ans_en":norm(ae),"desc_ta":norm(dt),"ans_ta":norm(at)})

pools=defaultdict(list)
for f in facts:
    pools[f["kind"]].append(f)

def distractors(f,n=3):
    # Prefer same semantic category and nearby pages; fall back to all facts.
    cand=[x for x in pools[f["kind"]] if x["ans_en"].lower()!=f["ans_en"].lower()]
    cand.sort(key=lambda x:(abs(x["page_en"]-f["page_en"]),x["ans_en"]))
    out=[]; used=set()
    for x in cand:
        a=x["ans_en"].lower()
        if a not in used:
            out.append(x); used.add(a)
        if len(out)==n: break
    if len(out)<n:
        for x in facts:
            a=x["ans_en"].lower()
            if a!=f["ans_en"].lower() and a not in used:
                out.append(x); used.add(a)
            if len(out)==n: break
    return out

def make_opts(f,seed):
    arr=[f]+distractors(f,3)
    random.Random(seed).shuffle(arr)
    return [x["ans_en"] for x in arr],[x["ans_ta"] for x in arr],arr.index(f)

questions=[]; qid=1
def add(page,qen,qta,oe,ot,c,een,eta,typ):
    global qid
    questions.append({
      "id":f"C11H14-Q{qid:04d}",
      "quiz":(qid-1)//20+1,
      "page_en":page,
      "q_en":qen,"q_ta":qta,
      "opts_en":oe,"opts_ta":ot,
      "correct":c,
      "exp_en":een,"exp_ta":eta,
      "type":typ
    })
    qid+=1

for i,f in enumerate(facts):
    een=f'{f["desc_en"]}: {f["ans_en"]}.'
    eta=f'{f["desc_ta"]}: {f["ans_ta"]}.'
    # Direct recall
    oe,ot,c=make_opts(f,14000+i*13)
    add(f["page_en"],
        f'What is the correct textbook answer for: {f["desc_en"]}?',
        f'இதற்கான சரியான பாடநூல் விடை எது: {f["desc_ta"]}?',
        oe,ot,c,een,eta,"direct")
    # Association
    oe,ot,c=make_opts(f,24000+i*17)
    add(f["page_en"],
        f'Which option is correctly associated with the following description: {f["desc_en"]}?',
        f'பின்வரும் விளக்கத்துடன் சரியாகப் பொருந்தும் விடை எது: {f["desc_ta"]}?',
        oe,ot,c,een,eta,"association")
    # Reverse recognition (same fact, different exam angle)
    oe,ot,c=make_opts(f,34000+i*19)
    add(f["page_en"],
        f'Identify the term/person/place that the textbook links with this fact: {f["desc_en"]}.',
        f'இந்த பாடநூல் உண்மையுடன் தொடர்புடைய பெயர்/சொல்/இடத்தைத் தேர்ந்தெடுக்கவும்: {f["desc_ta"]}.',
        oe,ot,c,een,eta,"recognition")

comb_en=["Both I and II are correct","I is correct; II is incorrect","I is incorrect; II is correct","Both I and II are incorrect"]
comb_ta=["I மற்றும் II இரண்டும் சரி","I சரி; II தவறு","I தவறு; II சரி","I மற்றும் II இரண்டும் தவறு"]
for i,f in enumerate(facts):
    g=facts[(i+1)%len(facts)]
    mode=i%4
    iok=mode in (0,1); iiok=mode in (0,2)
    wf=distractors(f,1)[0]; wg=distractors(g,1)[0]
    a1=f["ans_en"] if iok else wf["ans_en"]
    t1=f["ans_ta"] if iok else wf["ans_ta"]
    a2=g["ans_en"] if iiok else wg["ans_en"]
    t2=g["ans_ta"] if iiok else wg["ans_ta"]
    qen=f'Consider the following statements:\nI. {f["desc_en"]} — {a1}.\nII. {g["desc_en"]} — {a2}.\nWhich option is correct?'
    qta=f'பின்வரும் கூற்றுகளைக் கவனிக்கவும்:\nI. {f["desc_ta"]} — {t1}.\nII. {g["desc_ta"]} — {t2}.\nசரியான விடை எது?'
    exen=[
      "Both Statement I and Statement II are correct.",
      "Statement I is correct and Statement II is incorrect.",
      "Statement I is incorrect and Statement II is correct.",
      "Both Statement I and Statement II are incorrect."
    ][mode]
    exta=[
      "கூற்று I மற்றும் II இரண்டும் சரி.",
      "கூற்று I சரி; கூற்று II தவறு.",
      "கூற்று I தவறு; கூற்று II சரி.",
      "கூற்று I மற்றும் II இரண்டும் தவறு."
    ][mode]
    add(max(f["page_en"],g["page_en"]),qen,qta,comb_en,comb_ta,mode,exen,exta,"statement-analysis")

# De-duplicate exact question+options, then renumber.
unique=[]; seen_q=set()
for q in questions:
    sig=(q["q_en"],tuple(q["opts_en"]))
    if sig in seen_q: continue
    seen_q.add(sig)
    unique.append(q)
questions=unique
for i,q in enumerate(questions,1):
    q["id"]=f"C11H14-Q{i:04d}"
    q["quiz"]=(i-1)//20+1

quiz_count=(len(questions)+19)//20
sets=[{"id":i,"title_en":f"Quiz {i} · Competitive Review","title_ta":f"வினாடி வினா {i} · போட்டித் தேர்வு மீள்பார்வை"} for i in range(1,quiz_count+1)]
counts=Counter("ABCD"[q["correct"]] for q in questions)
sigs=set(); dups=0
for q in questions:
    s=(q["q_en"],tuple(q["opts_en"]))
    if s in sigs: dups+=1
    sigs.add(s)

out={"meta":{
  "board":"Tamil Nadu State Board",
  "class":11,
  "subject":"History",
  "edition":2025,
  "unit":14,
  "unit_en":"The Mughal Empire",
  "unit_ta":"முகலாயப் பேரரசு",
  "source":"Government of Tamil Nadu Higher Secondary First Year History, Revised Edition 2025, English and Tamil editions supplied by the user",
  "total_questions":len(questions),
  "base_facts":len(facts),
  "quiz_sets":sets,
  "question_style":"Maximum useful source-grounded bilingual competitive-exam coverage from Unit 14: Babur and the four foundational battles; Humayun and the Sur interregnum; Sher Shah's administration; Akbar's conquests, Rajput policy, Mansabdari and religious policy; Jahangir and Nur Jahan; Shah Jahan, Deccan, European settlements and Taj Mahal; Aurangzeb's Rajput, Sikh, Maratha and Deccan policies; Mughal society, economy, trade, religion, science and technology; architecture, painting, music and literature.",
  "quality_policy":"Four-option bilingual MCQs grounded in the supplied 2025 English and Tamil textbooks. Activities and low-value procedural material are excluded. Distinct textbook facts are reinforced through direct recall, association, recognition and statement-analysis formats. Source framing is retained even where a detail may differ from other historical accounts.",
  "page_reference_note":"page_en refers to the printed English textbook page.",
  "qa_all_four_options":all(len(q["opts_en"])==4 and len(q["opts_ta"])==4 for q in questions),
  "qa_valid_correct_indexes":all(0<=q["correct"]<4 for q in questions),
  "qa_duplicate_ids":len(questions)-len({q["id"] for q in questions}),
  "qa_exact_duplicate_question_options":dups,
  "qa_answer_position_counts":dict(counts)
},"questions":questions}

os.makedirs(os.path.dirname(OUT),exist_ok=True)
with open(OUT,"w",encoding="utf-8") as fp:
    json.dump(out,fp,ensure_ascii=False,indent=2)
print(f"Wrote {OUT}: {len(facts)} facts, {len(questions)} questions, {quiz_count} quizzes")
